From 2a8ae8de2e5daa9492d57049a7ce26b777934bcd Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:10:00 +0100
Subject: [PATCH] WidgetExplorer: create delegate buttons and badges only when
 shown

Every widget in the sidebar created two tool buttons, a badge and a
badge effect, though they only show on the hovered or a new widget,
which added to the stall when opening it. Load them on demand instead.

CCBUG: 460992
---
 .../contents/explorer/AppletDelegate.qml      | 230 +++++++++---------
 1 file changed, 121 insertions(+), 109 deletions(-)

diff --git a/desktoppackage/contents/explorer/AppletDelegate.qml b/desktoppackage/contents/explorer/AppletDelegate.qml
index bbf3740cc7..0ce7e332a2 100644
--- a/desktoppackage/contents/explorer/AppletDelegate.qml
+++ b/desktoppackage/contents/explorer/AppletDelegate.qml
@@ -21,12 +21,13 @@ Item {
     readonly property bool pendingUninstall: pendingUninstallTimer.applets.indexOf(pluginName) > -1
     readonly property bool pressed: tapHandler.pressed
     readonly property bool softwareRendering: GraphicsInfo.api === GraphicsInfo.Software
+    readonly property bool showBadge: ((running && GridView.isCurrentItem) || model.recent) ?? false

     width: list.cellWidth
     height: list.cellHeight

     Accessible.name: i18nc("@action:button accessible only, %1 is widget name", "Add %1", model.name)  + (model.isSupported ? "" : unsupportedTooltip.mainText)
-    Accessible.description: (model.isSupported ? "" : model.unsupportedMessage) + model.description + (overlayedBadge.visible ? overlayedBadge.Accessible.name : "")
+    Accessible.description: (model.isSupported ? "" : model.unsupportedMessage) + model.description + (badgeLoader.item?.accessibleName ?? "")
     Accessible.role: Accessible.Button

     HoverHandler {
@@ -156,129 +157,140 @@ Item {
                 }
             }

-            Item {
-                id: badgeMask
-                anchors.fill: parent
-
-                Rectangle {
-                    readonly property int offset: Math.round(Kirigami.Units.smallSpacing * 1.5)
-                    x: Math.round(-offset / 2)
-                    y: x
-                    width: overlayedBadge.width + offset
-                    height: overlayedBadge.height + offset
-                    radius: height
-                    visible: overlayedBadge.visible
-                }
-            }
-
-            KGraphicalEffects.BadgeEffect {
+            Loader {
+                id: badgeLoader
                 anchors.fill: parent
-                source: ShaderEffectSource {
-                    sourceItem: iconWidget
-                    hideSource: !softwareRendering
-                    live: false
-                }
-                mask: ShaderEffectSource {
-                    id: maskShaderSource
-                    sourceItem: badgeMask
-                    hideSource: true
-                    live: false
-                }
-            }
+                active: delegate.showBadge
+                sourceComponent: Item {
+                    readonly property string accessibleName: overlayedBadge.Accessible.name
+
+                    Item {
+                        id: badgeMask
+                        anchors.fill: parent
+
+                        Rectangle {
+                            readonly property int offset: Math.round(Kirigami.Units.smallSpacing * 1.5)
+                            x: Math.round(-offset / 2)
+                            y: x
+                            width: overlayedBadge.width + offset
+                            height: overlayedBadge.height + offset
+                            radius: height
+                        }
+                    }

-            Kirigami.Badge {
-                id: overlayedBadge
+                    KGraphicalEffects.BadgeEffect {
+                        anchors.fill: parent
+                        source: ShaderEffectSource {
+                            sourceItem: iconWidget
+                            hideSource: !softwareRendering
+                            live: false
+                        }
+                        mask: ShaderEffectSource {
+                            id: maskShaderSource
+                            sourceItem: badgeMask
+                            hideSource: true
+                            live: false
+                        }
+                    }

-                visible: ((running && delegate.GridView.isCurrentItem) || model.recent) ?? false
+                    Kirigami.Badge {
+                        id: overlayedBadge

-                type: (running && delegate.GridView.isCurrentItem) ? Kirigami.Badge.Type.Information : Kirigami.Badge.Type.Positive
+                        type: (running && delegate.GridView.isCurrentItem) ? Kirigami.Badge.Type.Information : Kirigami.Badge.Type.Positive

-                text: (running && delegate.GridView.isCurrentItem) ? running : i18ndc("plasma_shell_org.kde.plasma.desktop", "Text displayed on top of newly-installed widgets", "New!")
-                Accessible.name: running
-                    ? i18ncp("@info:other accessible for badge showing applet count", "%1 widget active", "%1 widgets active", running)
-                    : i18nc(" @info:other accessible for badge indicating new widget", "Recently installed")
+                        text: (running && delegate.GridView.isCurrentItem) ? running : i18ndc("plasma_shell_org.kde.plasma.desktop", "Text displayed on top of newly-installed widgets", "New!")
+                        Accessible.name: running
+                            ? i18ncp("@info:other accessible for badge showing applet count", "%1 widget active", "%1 widgets active", running)
+                            : i18nc(" @info:other accessible for badge indicating new widget", "Recently installed")

-                onTextChanged: maskShaderSource.scheduleUpdate()
-                onTypeChanged: maskShaderSource.scheduleUpdate()
-                onVisibleChanged: maskShaderSource.scheduleUpdate()
-            }
-
-            PlasmaComponents.ToolButton {
-                id: uninstallButton
-                anchors {
-                    top: parent.top
-                    right: parent.right
-                }
-                text: delegate.pendingUninstall ? i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:button tooltip and accessible cancel uninstall widget", "Cancel Uninstallation")
-                    : i18ndc("plasma_shell_org.kde.plasma.desktop","@action:button tooltip and accessible uninstall widget", "Mark for Uninstallation")
-                icon.name: delegate.pendingUninstall ? "edit-undo" : "edit-delete"
-                display: PlasmaComponents.AbstractButton.IconOnly
-                Accessible.description: delegate.pendingUninstall
-                    ? i18nc("@action:button accessible only, %1 is widget name", "Cancel pending uninstallation for widget %1", model.name)
-                    : i18nc("@action:button accessible only, %1 is widget name", "Mark widget %1 for uninstallation. Requires confirmation", model.name)
-                // we don't really "undo" anything but we'll pretend to the user that we do
-                PlasmaComponents.ToolTip.delay: Kirigami.Units.toolTipDelay
-                PlasmaComponents.ToolTip.visible: hovered || visualFocus
-                PlasmaComponents.ToolTip.text: text
-                flat: false
-                visible: (model.local && delegate.GridView.isCurrentItem && !dragHandler.active && !touchDragHandler.active) ?? false
-
-                onHoveredChanged: {
-                    if (hovered) {
-                        // hovering the uninstall button triggers onExited of the main mousearea
-                        delegate.GridView.view.currentIndex = index
+                        onTextChanged: maskShaderSource.scheduleUpdate()
+                        onTypeChanged: maskShaderSource.scheduleUpdate()
                     }
                 }
+            }

-                onClicked: {
-                    let pending = pendingUninstallTimer.applets
-                    if (delegate.pendingUninstall) {
-                        let index = pending.indexOf(pluginName)
-                        if (index > -1) {
-                            pending.splice(index, 1)
+            Loader {
+                anchors.fill: parent
+                active: delegate.GridView.isCurrentItem
+                sourceComponent: Item {
+                    PlasmaComponents.ToolButton {
+                        id: uninstallButton
+                        anchors {
+                            top: parent.top
+                            right: parent.right
+                        }
+                        text: delegate.pendingUninstall ? i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:button tooltip and accessible cancel uninstall widget", "Cancel Uninstallation")
+                            : i18ndc("plasma_shell_org.kde.plasma.desktop","@action:button tooltip and accessible uninstall widget", "Mark for Uninstallation")
+                        icon.name: delegate.pendingUninstall ? "edit-undo" : "edit-delete"
+                        display: PlasmaComponents.AbstractButton.IconOnly
+                        Accessible.description: delegate.pendingUninstall
+                            ? i18nc("@action:button accessible only, %1 is widget name", "Cancel pending uninstallation for widget %1", model.name)
+                            : i18nc("@action:button accessible only, %1 is widget name", "Mark widget %1 for uninstallation. Requires confirmation", model.name)
+                        // we don't really "undo" anything but we'll pretend to the user that we do
+                        PlasmaComponents.ToolTip.delay: Kirigami.Units.toolTipDelay
+                        PlasmaComponents.ToolTip.visible: hovered || visualFocus
+                        PlasmaComponents.ToolTip.text: text
+                        flat: false
+                        visible: (model.local && delegate.GridView.isCurrentItem && !dragHandler.active && !touchDragHandler.active) ?? false
+
+                        onHoveredChanged: {
+                            if (hovered) {
+                                // hovering the uninstall button triggers onExited of the main mousearea
+                                delegate.GridView.view.currentIndex = index
+                            }
                         }
-                    } else {
-                        pending.push(pluginName)
-                    }
-                    pendingUninstallTimer.applets = pending

-                    if (pending.length) {
-                        pendingUninstallTimer.restart()
-                    } else {
-                        pendingUninstallTimer.stop()
+                        onClicked: {
+                            let pending = pendingUninstallTimer.applets
+                            if (delegate.pendingUninstall) {
+                                let index = pending.indexOf(pluginName)
+                                if (index > -1) {
+                                    pending.splice(index, 1)
+                                }
+                            } else {
+                                pending.push(pluginName)
+                            }
+                            pendingUninstallTimer.applets = pending
+
+                            if (pending.length) {
+                                pendingUninstallTimer.restart()
+                            } else {
+                                pendingUninstallTimer.stop()
+                            }
+                        }
                     }
-                }
-            }

-            PlasmaComponents.ToolButton {
-                id: removeInstancesButton
-                anchors {
-                    top: parent.top
-                    right: uninstallButton.visible ? uninstallButton.left : parent.right
-                    rightMargin: uninstallButton.visible ? Kirigami.Units.smallSpacing : 0
-                }
-                text: i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:button", "Remove all instances")
-                display: PlasmaComponents.AbstractButton.IconOnly
-                icon.name: "edit-clear-all"
-                Accessible.description: i18ncp("@action:button accessible description, %1 number of instances %2 is widget name",
-                                               "Remove running instance of widget %2",
-                                               "Remove all %1 running instances of widget %2", running ,model.name)
-
-                // we don't really "undo" anything but we'll pretend to the user that we do
-                PlasmaComponents.ToolTip.delay: Kirigami.Units.toolTipDelay
-                PlasmaComponents.ToolTip.visible: hovered || visualFocus
-                PlasmaComponents.ToolTip.text: text
-                flat: false
-                visible: (running && delegate.GridView.isCurrentItem && !dragHandler.active) ?? false
-
-                onHoveredChanged: {
-                    if (hovered) {
-                        // hovering the uninstall button triggers onExited of the main mousearea
-                        delegate.GridView.view.currentIndex = index
+                    PlasmaComponents.ToolButton {
+                        id: removeInstancesButton
+                        anchors {
+                            top: parent.top
+                            right: uninstallButton.visible ? uninstallButton.left : parent.right
+                            rightMargin: uninstallButton.visible ? Kirigami.Units.smallSpacing : 0
+                        }
+                        text: i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:button", "Remove all instances")
+                        display: PlasmaComponents.AbstractButton.IconOnly
+                        icon.name: "edit-clear-all"
+                        Accessible.description: i18ncp("@action:button accessible description, %1 number of instances %2 is widget name",
+                                                       "Remove running instance of widget %2",
+                                                       "Remove all %1 running instances of widget %2", running ,model.name)
+
+                        // we don't really "undo" anything but we'll pretend to the user that we do
+                        PlasmaComponents.ToolTip.delay: Kirigami.Units.toolTipDelay
+                        PlasmaComponents.ToolTip.visible: hovered || visualFocus
+                        PlasmaComponents.ToolTip.text: text
+                        flat: false
+                        visible: (running && delegate.GridView.isCurrentItem && !dragHandler.active) ?? false
+
+                        onHoveredChanged: {
+                            if (hovered) {
+                                // hovering the uninstall button triggers onExited of the main mousearea
+                                delegate.GridView.view.currentIndex = index
+                            }
+                        }
+
+                        onClicked: widgetExplorer.removeAllInstances(pluginName)
                     }
                 }
-
-                onClicked: widgetExplorer.removeAllInstances(pluginName)
             }
         }
         Kirigami.Heading {
-- 
