From 886f4088f44c662aae88d04050c1f94ba0055039 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:20:35 +0100
Subject: [PATCH] shellprivate: look up applet icons with KIconLoader directly

QIcon::hasThemeIcon builds an icon engine and, when the applet has no
icon of its own, Qt then searches every theme directory a second time.
Asking KIconLoader directly does one cached lookup with the same result.

CCBUG: 460992
---
 components/shellprivate/CMakeLists.txt            | 1 +
 components/shellprivate/plasmaappletitemmodel.cpp | 3 ++-
 2 files changed, 3 insertions(+), 1 deletion(-)

diff --git a/components/shellprivate/CMakeLists.txt b/components/shellprivate/CMakeLists.txt
index f53047c07c..06c2493ccd 100644
--- a/components/shellprivate/CMakeLists.txt
+++ b/components/shellprivate/CMakeLists.txt
@@ -23,6 +23,7 @@ target_link_libraries(plasmashellprivateplugin PRIVATE
         Plasma::Activities
         KF6::TextWidgets
         KF6::Package
+        KF6::IconThemes
 )

 ecm_finalize_qml_module(plasmashellprivateplugin)
diff --git a/components/shellprivate/plasmaappletitemmodel.cpp b/components/shellprivate/plasmaappletitemmodel.cpp
index 9ac696f463..38695541ab 100644
--- a/components/shellprivate/plasmaappletitemmodel.cpp
+++ b/components/shellprivate/plasmaappletitemmodel.cpp
@@ -16,6 +16,7 @@
 #include "config-workspace.h"
 #include <KAboutData>
 #include <KConfig>
+#include <KIconLoader>
 #include <KJsonUtils>
 #include <KLocalizedString>
 #include <KPackage/PackageLoader>
@@ -281,7 +282,7 @@ QVariant PlasmaAppletItem::data(int role) const
     case Qt::DecorationRole:
         // null = not yet done, empty = no icon.
         if (m_iconName.isNull()) {
-            if (QIcon::hasThemeIcon(m_info.pluginId())) {
+            if (KIconLoader::global()->hasIcon(m_info.pluginId())) {
                 m_iconName = m_info.pluginId();
             } else if (!m_info.iconName().isEmpty()) {
                 if (m_info.iconName().startsWith(QLatin1String("/"))) {
-- 
